using CompilerBase;
// <auto-generated />

using System.Collections.Generic;

namespace CCompiler
{
    public partial class Parser : ParserBase<Token, TokenType>
{
        private ASTNode ParseExpression()
        {
            ASTNode expr = ParseAssignment();
            while (Match(TokenType.COMMA))
            {
                ASTNode right = ParseAssignment();
                // 逗号表达式：返回右边的值
                expr = right;
            }
            return expr;
        }

        private ASTNode ParseAssignment()
        {
            ASTNode left = ParseConditional();

            if (Match(TokenType.ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right);
            }
            else if (Match(TokenType.ADD_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "+");
            }
            else if (Match(TokenType.SUB_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "-");
            }
            else if (Match(TokenType.MUL_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "*");
            }
            else if (Match(TokenType.DIV_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "/");
            }
            else if (Match(TokenType.MOD_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "%");
            }
            else if (Match(TokenType.AND_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "&");
            }
            else if (Match(TokenType.OR_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "|");
            }
            else if (Match(TokenType.XOR_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "^");
            }
            else if (Match(TokenType.LSHIFT_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, "<<");
            }
            else if (Match(TokenType.RSHIFT_ASSIGN))
            {
                ASTNode right = ParseAssignment();
                return new Assignment(left, right, ">>");
            }

            return left;
        }

        private ASTNode ParseConditional()
        {
            ASTNode expr = ParseOr();
            if (Match(TokenType.QUESTION))
            {
                ASTNode trueExpr = ParseExpression();
                Expect(TokenType.COLON);
                ASTNode falseExpr = ParseExpression();
                return new ConditionalOp(expr, trueExpr, falseExpr);
            }
            return expr;
        }

        private ASTNode ParseOr()
        {
            ASTNode left = ParseAnd();

            while (Match(TokenType.OR))
            {
                string  op    = "||";
                ASTNode right = ParseAnd();
                left = new BinaryOp(op, left, right);
            }

            return left;
        }

        private ASTNode ParseAnd()
        {
            ASTNode left = ParseEquality();

            while (Match(TokenType.AND))
            {
                string  op    = "&&";
                ASTNode right = ParseEquality();
                left = new BinaryOp(op, left, right);
            }

            return left;
        }

        private ASTNode ParseEquality()
        {
            ASTNode left = ParseRelational();

            while (true)
            {
                if (Match(TokenType.EQ))
                {
                    string  op    = "==";
                    ASTNode right = ParseRelational();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.NE))
                {
                    string  op    = "!=";
                    ASTNode right = ParseRelational();
                    left = new BinaryOp(op, left, right);
                }
                else
                {
                    break;
                }
            }

            return left;
        }

        private ASTNode ParseRelational()
        {
            ASTNode left = ParseBitwiseOr();

            while (true)
            {
                if (Match(TokenType.LT))
                {
                    string  op    = "<";
                    ASTNode right = ParseShift();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.LE))
                {
                    string  op    = "<=";
                    ASTNode right = ParseShift();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.GT))
                {
                    string  op    = ">";
                    ASTNode right = ParseShift();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.GE))
                {
                    string  op    = ">=";
                    ASTNode right = ParseShift();
                    left = new BinaryOp(op, left, right);
                }
                else
                {
                    break;
                }
            }

            return left;
        }

        private ASTNode ParseShift()
        {
            ASTNode left = ParseAdditive();

            while (true)
            {
                if (Match(TokenType.LSHIFT))
                {
                    string  op    = "<<";
                    ASTNode right = ParseAdditive();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.RSHIFT))
                {
                    string  op    = ">>";
                    ASTNode right = ParseAdditive();
                    left = new BinaryOp(op, left, right);
                }
                else
                {
                    break;
                }
            }

            return left;
        }

        private ASTNode ParseAdditive()
        {
            ASTNode left = ParseMultiplicative();

            while (true)
            {
                if (Match(TokenType.PLUS))
                {
                    string  op    = "+";
                    ASTNode right = ParseMultiplicative();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.MINUS))
                {
                    string  op    = "-";
                    ASTNode right = ParseMultiplicative();
                    left = new BinaryOp(op, left, right);
                }
                else
                {
                    break;
                }
            }

            return left;
        }

        private ASTNode ParseBitwiseOr()
        {
            ASTNode left = ParseBitwiseXor();

            while (Match(TokenType.PIPE))
            {
                string  op    = "|";
                ASTNode right = ParseBitwiseXor();
                left = new BinaryOp(op, left, right);
            }

            return left;
        }

        private ASTNode ParseBitwiseXor()
        {
            ASTNode left = ParseBitwiseAnd();

            while (Match(TokenType.CARET))
            {
                string  op    = "^";
                ASTNode right = ParseBitwiseAnd();
                left = new BinaryOp(op, left, right);
            }

            return left;
        }

        private ASTNode ParseBitwiseAnd()
        {
            ASTNode left = ParseShift();

            while (Match(TokenType.AMPERSAND))
            {
                string  op    = "&";
                ASTNode right = ParseShift();
                left = new BinaryOp(op, left, right);
            }

            return left;
        }

        private ASTNode ParseMultiplicative()
        {
            ASTNode left = ParseUnary();

            while (true)
            {
                if (Match(TokenType.STAR))
                {
                    string  op    = "*";
                    ASTNode right = ParseUnary();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.SLASH))
                {
                    string  op    = "/";
                    ASTNode right = ParseUnary();
                    left = new BinaryOp(op, left, right);
                }
                else if (Match(TokenType.PERCENT))
                {
                    string  op    = "%";
                    ASTNode right = ParseUnary();
                    left = new BinaryOp(op, left, right);
                }
                else
                {
                    break;
                }
            }

            return left;
        }

        private ASTNode ParseUnary()
        {
            // 处理类型转换 (type) expression
            if (Match(TokenType.LPAREN))
            {
                // 检查是否是类型转换（支持基本类型、typedef、定宽整数、struct/union/enum、以及未知标识符）
                // 未知标识符也可能是合法C类型(如uid_t, pid_t, mode_t来自POSIX头文件)
                // 但只有当后跟 ) * ( 时才视为类型(而非变量表达式)
                bool isTypedef = Current().Type == TokenType.IDENTIFIER &&
                                 program.TypeDefs.ContainsKey(Current().Value.ToString());
                bool isUnknownTypeIdent = false;
                if (Current().Type == TokenType.IDENTIFIER && !isTypedef)
                {
                    var next = Peek(1).Type;
                    if (next == TokenType.RPAREN)
                    {
                        // (identifier) — 可能是cast或括号表达式. 看)后的token.
                        var after = Peek(2).Type;
                        // 如果)后是二元/比较运算符, 说明是括号表达式如(e2)>0, 不是cast
                        isUnknownTypeIdent = !(after == TokenType.GT || after == TokenType.LT ||
                            after == TokenType.GE || after == TokenType.LE ||
                            after == TokenType.EQ || after == TokenType.NE ||
                            after == TokenType.PLUS || after == TokenType.MINUS ||
                            after == TokenType.STAR || after == TokenType.SLASH ||
                            after == TokenType.PERCENT || after == TokenType.AND ||
                            after == TokenType.OR || after == TokenType.AMPERSAND ||
                            after == TokenType.PIPE || after == TokenType.QUESTION ||
                            after == TokenType.COLON || after == TokenType.ASSIGN ||
                            after == TokenType.SEMICOLON || after == TokenType.COMMA ||
                            after == TokenType.RBRACKET || after == TokenType.ARROW ||
                            after == TokenType.DOT || after == TokenType.LPAREN ||
                            after == TokenType.INCREMENT || after == TokenType.DECREMENT);
                    }
                    else
                    {
                        // (identifier *) → 可能是cast或乘法表达式
                        // 如果*后面是数字或标识符，则是乘法表达式如 (w*2)，不是cast (w*)expr
                        if (next == TokenType.STAR)
                        {
                            var afterStar = Peek(2).Type;
                            isUnknownTypeIdent = !(afterStar == TokenType.NUMBER || afterStar == TokenType.IDENTIFIER);
                        }
                    }
                }
                if (Current().Type == TokenType.INT    || Current().Type == TokenType.VOID  ||
                    Current().Type == TokenType.CHAR   || Current().Type == TokenType.FLOAT ||
                    Current().Type == TokenType.DOUBLE ||
                    Current().Type == TokenType.SHORT  || Current().Type == TokenType.LONG     ||
                    Current().Type == TokenType.SIGNED || Current().Type == TokenType.UNSIGNED ||
                    Current().Type == TokenType.CONST  || Current().Type == TokenType.VOLATILE ||
                    Current().Type == TokenType.STRUCT || Current().Type == TokenType.UNION  ||
                    Current().Type == TokenType.ENUM   || Current().Type == TokenType.BOOL   ||
                    Current().Type == TokenType.INT8   || Current().Type == TokenType.INT16  ||
                    Current().Type == TokenType.INT32  || Current().Type == TokenType.INT64  ||
                    Current().Type == TokenType.UINT8  || Current().Type == TokenType.UINT16 ||
                    Current().Type == TokenType.UINT32 || Current().Type == TokenType.UINT64 ||
                    Current().Type == TokenType.INTPTR_T || Current().Type == TokenType.UINTPTR_T ||
                    Current().Type == TokenType.SIZE_T   || Current().Type == TokenType.SSIZE_T ||
                    Current().Type == TokenType.PTRDIFF_T ||
                    isTypedef || isUnknownTypeIdent)
                {
                    var typeName = "";

                    // 处理 const/volatile 修饰符
                    while (Current().Type == TokenType.CONST || Current().Type == TokenType.VOLATILE)
                    {
                        typeName += Current().Value.ToString() + " ";
                        Advance();
                    }

                    // 处理基本类型
                    Token typeToken = Advance();
                    typeName += typeToken.Value.ToString();

                    // 处理其他类型修饰符
                    while (Current().Type == TokenType.LONG || Current().Type == TokenType.SHORT || 
                           Current().Type == TokenType.SIGNED || Current().Type == TokenType.UNSIGNED ||
                           Current().Type == TokenType.CHAR || Current().Type == TokenType.INT ||
                           Current().Type == TokenType.FLOAT || Current().Type == TokenType.DOUBLE ||
                           Current().Type == TokenType.VOID ||
                           Current().Type == TokenType.IDENTIFIER) // struct NAME → consume name
                    {
                        typeName += " " + Advance().Value.ToString();
                    }
                    // 跳过 struct/union/enum 的内联定义 { ... }
                    if (Current().Type == TokenType.LBRACE)
                    {
                        int depth = 1; Advance();
                        while (depth > 0 && Current().Type != TokenType.EOF)
                        {
                            if (Current().Type == TokenType.LBRACE) depth++;
                            else if (Current().Type == TokenType.RBRACE) depth--;
                            if (depth > 0) Advance();
                        }
                    }

                    // 处理函数指针类型: double(*)(void), int (**)(params),
                    // 以及嵌套函数指针: void(*(*)(void*,const char*))(void)
                    while (Current().Type == TokenType.LPAREN && Peek(1).Type == TokenType.STAR)
                    {
                        Advance(); // (
                        while (Match(TokenType.STAR))
                            typeName += "*";
                        // 使用括号计数找到匹配的 )，支持嵌套 (*( 模式
                        int fpParenCount = 1;
                        while (fpParenCount > 0 && Current().Type != TokenType.EOF)
                        {
                            if (Current().Type == TokenType.LPAREN) fpParenCount++;
                            else if (Current().Type == TokenType.RPAREN) { fpParenCount--; if (fpParenCount == 0) { Advance(); break; } }
                            Advance();
                        }
                        // 跳过后续函数参数列表: (void*, const char*), (void)
                        while (Match(TokenType.LPAREN))
                        {
                            int depth = 1;
                            while (depth > 0 && Current().Type != TokenType.EOF)
                            {
                                if (Current().Type == TokenType.LPAREN) depth++;
                                else if (Current().Type == TokenType.RPAREN) { depth--; if (depth == 0) { Advance(); break; } }
                                Advance();
                            }
                        }
                    }

                    // 处理指针类型
                    while (Match(TokenType.STAR))
                    {
                        typeName += "*";
                        while (Current().Type == TokenType.CONST || Current().Type == TokenType.VOLATILE)
                            typeName += " " + Advance().Value.ToString();
                    }

                    // 处理指针后的函数指针: type*(*)(params), type*(**)(params)
                    while (Current().Type == TokenType.LPAREN && Peek(1).Type == TokenType.STAR)
                    {
                        Advance(); // (
                        while (Match(TokenType.STAR))
                            typeName += "*";
                        // 使用括号计数找到匹配的 )
                        int fpParenCount = 1;
                        while (fpParenCount > 0 && Current().Type != TokenType.EOF)
                        {
                            if (Current().Type == TokenType.LPAREN) fpParenCount++;
                            else if (Current().Type == TokenType.RPAREN) { fpParenCount--; if (fpParenCount == 0) { Advance(); break; } }
                            Advance();
                        }
                        // 跳过后续函数参数列表
                        while (Match(TokenType.LPAREN))
                        {
                            int depth = 1;
                            while (depth > 0 && Current().Type != TokenType.EOF)
                            {
                                if (Current().Type == TokenType.LPAREN) depth++;
                                else if (Current().Type == TokenType.RPAREN) { depth--; if (depth == 0) { Advance(); break; } }
                                Advance();
                            }
                        }
                    }

                    // 处理数组类型: type[], type[N]
                    while (Match(TokenType.LBRACKET))
                    {
                        if (Current().Type == TokenType.NUMBER)
                            typeName += "[" + Advance().Value.ToString() + "]";
                        else
                            typeName += "[]";
                        Expect(TokenType.RBRACKET);
                    }

                    Expect(TokenType.RPAREN);
                    // 如果后面是 { ... }，则是 compound literal —— **不支持，而且要响亮地停**
                    // （v0.96.183 / patches/0008）。
                    //
                    // 原先这里是 `return ParseInitializerList();`，把初始化列表当表达式返回，
                    // 但 `ArrayInitializer` 的**代码生成只挂在变量声明上**
                    // （`varDecl.Initializer is ArrayInitializer`，见 CodeGenerator.Functions/Statements），
                    // 表达式位置**没有任何一处会产出它的地址** ⇒ 编出来的代码把上一个寄存器的值
                    // （正好是刚推入的"点数"）当成指针推给被调函数。实测：
                    //   `ui_polygon((int[]){92,215,…}, 3, …)` 宿主收到 pts=3，去地址 3 读坐标、
                    //   越界就地停 ⇒ **静默什么都不画**，而编译**通过、不报错**。
                    // 桌面把汇编打出来一眼可辨：具名数组是 `move R0 R12 / sub R0 #28 / push R0`，
                    // 复合字面量是 `move R0 #3 / push R0`。（真机 + 桌面两处验过，见 CHANGELOG v0.96.182）
                    //
                    // 为什么是报错而不是把它实现出来：要让它成立，得在**表达式中间**开一个帧内临时槽，
                    // 而"临时槽与局部变量撞车"正是 0002 修过的那类事故（asm 结果的暂存槽撞上第一个
                    // 局部变量）。做对需要一遍真正的临时分配，不该在这里随手加一个。
                    // 这类"编得过、跑起来才错"的坑，报错比默默编坏便宜得多。
                    if (Current().Type == TokenType.LBRACE)
                    {
                        throw Error(ErrorCode.Parser_UnexpectedToken,
                            "本编译器不支持复合字面量“(类型[]){…}”：请改用具名局部数组再传，"
                            + "例如 int pts[6]; pts[0] = 92; … 然后传 pts");
                    }
                    ASTNode expr = ParseUnary();
                    return new CastExpr(typeName, expr);
                }
                else
                {
                    // 不是类型转换，(已经被Match消耗了)，解析为括号表达式
                    // 支持赋值表达式: (x = y) != z 和逗号表达式: (a, b, c)
                    ASTNode expr = ParseExpression();
                    while (Match(TokenType.COMMA))
                    {
                        var right = ParseConditional();
                        expr = new BinaryOp(",", expr, right);
                    }
                    Expect(TokenType.RPAREN);
                    // 对括号表达式结果应用后缀运算符: (expr)[idx], (expr)->member, (expr).member, (expr)(args)
                    while (true)
                    {
                        if (Match(TokenType.LBRACKET))
                        {
                            List<ASTNode> indices = new List<ASTNode>();
                            indices.Add(ParseExpression());
                            Expect(TokenType.RBRACKET);
                            while (Match(TokenType.LBRACKET))
                            {
                                indices.Add(ParseExpression());
                                Expect(TokenType.RBRACKET);
                            }
                            expr = new ArrayAccess(expr, indices);
                        }
                        else if (Match(TokenType.DOT))
                        {
                            string member = Expect(TokenType.IDENTIFIER).Value.ToString();
                            expr = new MemberAccess(expr, member, false);
                        }
                        else if (Match(TokenType.ARROW))
                        {
                            string member = Expect(TokenType.IDENTIFIER).Value.ToString();
                            expr = new MemberAccess(expr, member, true);
                        }
                        else if (Match(TokenType.LPAREN))
                        {
                            List<ASTNode> args = new List<ASTNode>();
                            if (!Match(TokenType.RPAREN))
                            {
                                args.Add(ParseAssignment());
                                while (Match(TokenType.COMMA))
                                    args.Add(ParseAssignment());
                                Expect(TokenType.RPAREN);
                            }
                            expr = new FunctionCall(null, args) { Callee = expr };
                        }
                        else if (Match(TokenType.INCREMENT))
                            expr = new UnaryOp("++", expr, true);
                        else if (Match(TokenType.DECREMENT))
                            expr = new UnaryOp("--", expr, true);
                        else break;
                    }
                    return expr;
                }
            }

            if (Match(TokenType.MINUS))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("-", operand);
            }

            // 一元加运算符 + (如 +x, +5)
            if (Match(TokenType.PLUS))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("+", operand);
            }

            if (Match(TokenType.NOT))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("!", operand);
            }

            // 按位取反运算符 ~
            if (Match(TokenType.TILDE))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("~", operand);
            }

            // 地址运算符 &
            if (Match(TokenType.AMPERSAND))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("&", operand);
            }

            // 解引用运算符 *
            if (Match(TokenType.STAR))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("*", operand);
            }

            // sizeof 运算符
            if (Match(TokenType.SIZEOF))
            {
                if (Match(TokenType.LPAREN))
                {
                    // 处理 sizeof(类型) 形式 (包含基本类型+定宽整数+typedef)
                    bool isTypedef = Current().Type == TokenType.IDENTIFIER &&
                                     program.TypeDefs.ContainsKey(Current().Value.ToString());
                    if (Current().Type == TokenType.INT    || Current().Type == TokenType.VOID  ||
                        Current().Type == TokenType.CHAR   || Current().Type == TokenType.FLOAT ||
                        Current().Type == TokenType.DOUBLE || Current().Type == TokenType.BOOL  ||
                        Current().Type == TokenType.SHORT  || Current().Type == TokenType.LONG  ||
                        Current().Type == TokenType.SIGNED || Current().Type == TokenType.UNSIGNED ||
                        Current().Type == TokenType.CONST  || Current().Type == TokenType.VOLATILE ||
                        Current().Type == TokenType.STRUCT || Current().Type == TokenType.UNION ||
                        Current().Type == TokenType.ENUM   ||
                        Current().Type == TokenType.INT8   || Current().Type == TokenType.INT16  ||
                        Current().Type == TokenType.INT32  || Current().Type == TokenType.INT64  ||
                        Current().Type == TokenType.UINT8  || Current().Type == TokenType.UINT16 ||
                        Current().Type == TokenType.UINT32 || Current().Type == TokenType.UINT64 ||
                        Current().Type == TokenType.INTPTR_T || Current().Type == TokenType.UINTPTR_T ||
                        Current().Type == TokenType.SIZE_T || Current().Type == TokenType.SSIZE_T ||
                        Current().Type == TokenType.PTRDIFF_T ||
                        isTypedef)
                    {
                        string typeName = "";

                        // 处理 const 修饰符
                        while (Current().Type == TokenType.CONST)
                        {
                            typeName += Current().Value.ToString() + " ";
                            Advance();
                        }

                        // 处理 struct/union 类型
                        if (Current().Type == TokenType.STRUCT || Current().Type == TokenType.UNION)
                        {
                            typeName += Advance().Value.ToString() + " ";
                            if (Current().Type == TokenType.IDENTIFIER)
                                typeName += Advance().Value.ToString();
                        }
                        else
                        {
                            // 处理基本类型
                            Token typeToken = Advance();
                            typeName += typeToken.Value.ToString();

                            // 处理其他类型修饰符 (unsigned int, signed char, etc.)
                            while (Current().Type == TokenType.LONG || Current().Type == TokenType.SHORT || Current().Type == TokenType.SIGNED || Current().Type == TokenType.UNSIGNED || Current().Type == TokenType.INT || Current().Type == TokenType.CHAR || Current().Type == TokenType.DOUBLE)
                            {
                                typeName += " " + Advance().Value.ToString();
                            }
                        }

                        // 处理指针修饰符 (如 sizeof(struct Point*))
                        while (Current().Type == TokenType.STAR)
                        {
                            typeName += Advance().Value.ToString();
                        }

                        Expect(TokenType.RPAREN);
                        return new SizeOfNode(typeName.Trim());
                    }
                    else
                    {
                        // 处理 sizeof(表达式) 形式
                        // 但如果标识符是 typedef/struct/union 名，仍作为类型处理
                        if (Current().Type == TokenType.IDENTIFIER)
                        {
                            string identName = Current().Value.ToString();
                            if (program.TypeDefs.ContainsKey(identName) ||
                                program.Structs.ContainsKey(identName) ||
                                program.Unions.ContainsKey(identName))
                            {
                                // 作为类型名处理
                                string typeName = Advance().Value.ToString();
                                while (Current().Type == TokenType.STAR) typeName += "*";
                                Expect(TokenType.RPAREN);
                                return new SizeOfNode(typeName);
                            }
                        }
                        ASTNode expr = ParseExpression();
                        Expect(TokenType.RPAREN);
                        return new SizeOfNode(null, expr);
                    }
                }
                else
                {
                    // 处理 sizeof 标识符 形式
                    ASTNode expr = ParsePostfix();
                    return new SizeOfNode(null, expr);
                }
            }

            // 前缀自增和自减
            if (Match(TokenType.INCREMENT))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("++", operand, false);
            }
            if (Match(TokenType.DECREMENT))
            {
                ASTNode operand = ParseUnary();
                return new UnaryOp("--", operand, false);
            }

            return ParsePostfix();
        }

        private ASTNode ParsePostfix()
        {
            ASTNode node = ParsePrimary();

            while (true)
            {
                // 数组访问
                if (Match(TokenType.LBRACKET))
                {
                    List<ASTNode> indices = new List<ASTNode>();
                    indices.Add(ParseExpression());
                    Expect(TokenType.RBRACKET);

                    // 检查是否有更多维度
                    while (Match(TokenType.LBRACKET))
                    {
                        indices.Add(ParseExpression());
                        Expect(TokenType.RBRACKET);
                    }

                    node = new ArrayAccess(node, indices);
                }
                // 成员访问 .
                else if (Match(TokenType.DOT))
                {
                    string memberName = Expect(TokenType.IDENTIFIER).Value.ToString();
                    node = new MemberAccess(node, memberName, false);
                }
                // 指针成员访问 ->
                else if (Match(TokenType.ARROW))
                {
                    string memberName = Expect(TokenType.IDENTIFIER).Value.ToString();
                    node = new MemberAccess(node, memberName, true);
                }
                // 后缀自增和自减
                else if (Match(TokenType.INCREMENT))
                {
                    node = new UnaryOp("++", node, true);
                }
                else if (Match(TokenType.DECREMENT))
                {
                    node = new UnaryOp("--", node, true);
                }
                // 函数调用（支持直接调用和函数指针调用）
                else if (Match(TokenType.LPAREN))
                {
                    List<ASTNode> args = new List<ASTNode>();
                    if (!Match(TokenType.RPAREN))
                    {
                        try {
                            args.Add(ParseAssignment());
                            while (Match(TokenType.COMMA))
                            {
                                args.Add(ParseAssignment());
                            }
                            Expect(TokenType.RPAREN);
                        } catch (System.Exception) {
                            // 容错: 跳过无法解析的参数直到 )
                            int ad = 1;
                            while (ad > 0 && Current().Type != TokenType.EOF) {
                                if (Current().Type == TokenType.RBRACE
                                    || Current().Type == TokenType.SEMICOLON) throw; // 结构性错误
                                if (Current().Type == TokenType.LPAREN) ad++;
                                else if (Current().Type == TokenType.RPAREN) {
                                    ad--;
                                    if (ad == 0) { Advance(); break; }
                                }
                                Advance();
                            }
                        }
                    }

                    // 直接调用: node 是 Identifier → 用 Name 做标签调用
                    // 间接调用: node 是其他表达式 → 用 Callee 生成间接 CALL
                    if (node is Identifier ident)
                    {
                        // 在C99中，函数可以隐式声明
                        if (VMLPlugins.CompilerOptionsContext.Current.DebugMode)
                        Console.WriteLine($"警告: 在第 {Current().Line} 行，调用了可能未声明的函数 '{ident.Name}'（将在链接阶段处理）");
                        node = new FunctionCall(ident.Name, args) { Callee = ident };
                    }
                    else
                    {
                        // 函数指针调用: (*fp)(args) 或 fp(args) 等
                        node = new FunctionCall(null, args) { Callee = node };
                    }
                }
                else
                {
                    break;
                }
            }

            return node;
        }

        private ASTNode ParsePrimary()
        {
            // asm 表达式: asm("SYSCALL #40") 或 return asm("mov r0, ${a}")
            if (Current().Type == TokenType.ASM)
            {
                Advance(); // consume asm
                Expect(TokenType.LPAREN);
                string asmCode = Expect(TokenType.STRING).Value.ToString();
                Expect(TokenType.RPAREN);
                return new AsmStatement(asmCode); // AsmStatement 可作表达式用
            }

            // 数字
            if (Current().Type == TokenType.NUMBER)
            {
                Token  token = Advance();
                object value = token.Value;

                // 从源代码中提取常量后缀
                string suffix = ExtractConstantSuffix(token);

                return new NumberLiteral(value, suffix);
            }

            // 字符串 (byte/wide/unicode)
            if (Current().Type == TokenType.STRING)
            {
                string value = Advance().Value.ToString();
                return new StringLiteral(value, StringWidth.Char);
            }
            if (Current().Type == TokenType.WSTRING)
            {
                string value = Advance().Value.ToString();
                return new StringLiteral(value, StringWidth.Wide);
            }
            if (Current().Type == TokenType.USTRING)
            {
                string value = Advance().Value.ToString();
                return new StringLiteral(value, StringWidth.Unicode);
            }

            // 字符字面量
            if (Current().Type == TokenType.CHAR_LITERAL)
            {
                char value = (char)Advance().Value;
                return new CharLiteral(value);
            }
            if (Current().Type == TokenType.WCHAR_LITERAL)
            {
                int codePoint = int.Parse(Advance().Value.ToString());
                return new CharLiteral((char)codePoint);
            }
            if (Current().Type == TokenType.UCHAR_LITERAL)
            {
                int codePoint = int.Parse(Advance().Value.ToString());
                return new CharLiteral((char)codePoint);
            }

            // 标识符
            if (Current().Type == TokenType.IDENTIFIER)
            {
                string name = Advance().Value.ToString();
                return new Identifier(name);
            }

            // 括号表达式 - 已在ParseUnary中处理，这里不再重复
            // 保留此分支以处理意外情况
            if (Match(TokenType.LPAREN))
            {
                ASTNode expr = ParseConditional();
                Expect(TokenType.RPAREN);
                return expr;
            }

            // 数组初始化表达式（仅支持简单情况）
            // 注意：使用 ParseAssignment 而非 ParseExpression，因为 ParseExpression 会
            // 把逗号当作逗号运算符处理（吞噬左值只返回右值），导致 {10, 20} 变成只有一个元素 20
            if (Match(TokenType.LBRACE))
            {
                List<ASTNode> elements = new List<ASTNode>();
                if (!Match(TokenType.RBRACE))
                {
                    while (true)
                    {
                        elements.Add(ParseAssignment());
                        if (!Match(TokenType.COMMA))
                        {
                            break;
                        }
                        // C99: 容忍尾部逗号 (如 {1,2,3,})
                        if (Current().Type == TokenType.RBRACE)
                            break;
                    }
                    Expect(TokenType.RBRACE);
                }
                return new ArrayInitializer(elements);
            }

            // 容错: 遇到未预期的token返回空节点并跳过
            if (Current().Type == TokenType.RBRACE || Current().Type == TokenType.SEMICOLON || Current().Type == TokenType.COMMA
                || Current().Type == TokenType.STRUCT || Current().Type == TokenType.UNION || Current().Type == TokenType.ENUM
                || Current().Type == TokenType.NUMBER || Current().Type == TokenType.STAR)
            {
                // 对于 struct/union/enum/STAR，跳过后续修饰符
                if (Current().Type == TokenType.STRUCT || Current().Type == TokenType.UNION || Current().Type == TokenType.ENUM || Current().Type == TokenType.STAR)
                {
                    Advance(); // skip token
                    if (Current().Type == TokenType.IDENTIFIER) Advance(); // skip tag name
                    while (Current().Type == TokenType.STAR) Advance(); // skip more pointers
                }
                else Advance(); // skip NUMBER, RBRACE, etc.
                return new NumberLiteral(0);
            }

            throw Error($"意外的 token: {Current()}");
        }

        private VariableDecl ParseVariableDecl(string typeName, string name)
        {
            VariableDecl var = new VariableDecl(name, typeName);

            // 检查是否为数组声明（支持多维）
            while (Match(TokenType.LBRACKET))
            {
                var.IsArray = true;

                // 解析数组大小（如果有）
                // 空括号: type name[] = {...};
                if (Current().Type == TokenType.RBRACKET)
                {
                    var.Dimensions.Add(null);
                }
                else
                {
                    // 解析数组维度表达式（支持常量表达式如 MAXPATHSIZE + 8 或运行时VLA如 arr[n]）
                    // 先用 ParseExpression 解析整个维度（包括 + - * / 等二元运算）
                    ASTNode dimExpr = ParseExpression();

                    // 能折成常量的（**含 `BW * BH` 这种宏 × 宏**）记为编译期维度 —— 只认
                    // 裸字面量的话，`int b[BW*BH]` 会静默按 1 个元素分配（见 TryConstInt 注释）。
                    if (TryConstInt(dimExpr, out var dim))
                    {
                        if (var.ArraySize == null) var.ArraySize = dim;
                        else var.ArraySize *= dim;
                        var.Dimensions.Add(dim);
                    }
                    else
                    {
                        // 常量表达式或 VLA: 运行时维度 (如 int arr[n] 或 int arr[MAX+8])
                        var.VlaDimensions ??= new List<ASTNode>();
                        var.VlaDimensions.Add(dimExpr);
                        var.Dimensions.Add(null); // 占位
                    }
                }

                Expect(TokenType.RBRACKET); // 期望 ]
            }
            
            if (Match(TokenType.ASSIGN))
            {
                if (Current().Type == TokenType.LBRACE)
                {
                    // 处理数组初始化器 { expr, expr, ... } 或 { { ... }, { ... } }
                    var.Initializer = ParseInitializerList();
                }
                else
                {
                    var.Initializer = ParseAssignment();
                }
            }
            return var;
        }

        /// <summary>
        /// 解析数组/结构体初始化器列表 { expr, expr, ... } 或 { { ... }, { ... } }
        /// </summary>
        private ASTNode ParseInitializerList()
        {
            Expect(TokenType.LBRACE); // {
            var elements = new List<ASTNode>();

            while (Current().Type != TokenType.RBRACE && Current().Type != TokenType.EOF)
            {
                ASTNode elem;
                // C99 designated initializer: .field = val 或 [index] = val
                if (Current().Type == TokenType.DOT)
                {
                    Advance(); // 跳过 .
                    string fieldName = Expect(TokenType.IDENTIFIER).Value.ToString();
                    if (Match(TokenType.ASSIGN)) { }
                    elem = ParseAssignment();
                    // Store as simple expression (the assignment handles the value)
                }
                else if (Current().Type == TokenType.LBRACKET)
                {
                    Advance(); // 跳过 [
                    ASTNode index = ParseExpression();
                    Expect(TokenType.RBRACKET);
                    if (Match(TokenType.ASSIGN)) { }
                    elem = ParseAssignment();
                }
                else if (Current().Type == TokenType.LBRACE)
                {
                    // 嵌套初始化器 { ... }
                    elem = ParseInitializerList();
                }
                else
                {
                    // 使用 ParseAssignment 而非 ParseExpression，避免逗号运算符吞噬元素
                    elem = ParseAssignment();
                }

                elements.Add(elem);

                if (Current().Type == TokenType.COMMA)
                {
                    Advance(); // 跳过逗号
                }
                else
                {
                    break; // 没有逗号，结束
                }
            }

            Expect(TokenType.RBRACE); // }
            return new ArrayInitializer(elements);
        }

        /// <summary>
        /// 解析C99标准的类型说明符
        /// 根据C99标准，类型说明符可以是：
        /// - void, char, short, int, long, float, double
        /// - signed, unsigned (可以单独使用或与char/short/int/long组合)
        /// - 枚举、结构体、联合体类型
        /// </summary>
        private string ParseTypeSpecifiers()
        {
            var typeSpecifiers = new List<string>();
            var hasSigned      = false;
            var hasUnsigned    = false;
            var hasVoid        = false;
            var hasChar        = false;
            var hasShort       = false;
            var hasInt         = false;
            var hasLong        = false;
            var hasFloat       = false;
            var hasDouble      = false;

            // 收集所有类型说明符
            while (true)
            {
                var currentType = Current().Type;

                // 处理const和volatile限定符
                if (currentType is TokenType.CONST or TokenType.VOLATILE)
                {
                    typeSpecifiers.Add(Advance().Value.ToString());
                    continue;
                }

                if (currentType == TokenType.SIGNED)
                {
                    if (hasSigned || hasUnsigned)
                        throw Error("类型说明符冲突：signed和unsigned不能同时使用");
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasSigned = true;
                }
                else if (currentType == TokenType.UNSIGNED)
                {
                    if (hasSigned || hasUnsigned)
                        throw Error("类型说明符冲突：signed和unsigned不能同时使用");
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasUnsigned = true;
                }
                else if (currentType == TokenType.VOID)
                {
                    if (hasVoid || hasChar || hasShort || hasInt || hasLong || hasFloat || hasDouble)
                        throw Error("类型说明符冲突：void不能与其他类型组合");
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasVoid = true;
                    break; // void是完整的类型
                }
                else if (currentType == TokenType.CHAR)
                {
                    if (hasChar || hasShort || hasInt || hasLong || hasFloat || hasDouble || hasVoid)
                        throw Error("类型说明符冲突：char不能与其他基本类型组合");
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasChar = true;
                    break; // char是完整的类型（可以带signed/unsigned）
                }
                else if (currentType == TokenType.SHORT)
                {
                    if (hasShort || hasChar || hasLong || hasFloat || hasDouble || hasVoid)
                        throw Error("类型说明符冲突：short不能与char/long/float/double组合");
                    if (hasInt) // short int是允许的，但通常简写为short
                        break;
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasShort = true;
                }
                else if (currentType == TokenType.INT)
                {
                    if (hasInt || hasChar || hasFloat || hasDouble || hasVoid)
                        throw Error("类型说明符冲突：int不能与char/float/double组合");
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasInt = true;
                    break; // int是完整的类型（可以带signed/unsigned/short/long）
                }
                else if (currentType == TokenType.LONG)
                {
                    if (hasChar || hasShort || hasFloat || hasDouble || hasVoid)
                        throw Error("类型说明符冲突：long不能与char/short/float/double组合");
                    if (hasInt && typeSpecifiers.Count == 2) // long int是允许的，但通常简写为long
                        break;
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasLong = true;
                    // 支持 long long (C99扩展)
                    if (Current().Type == TokenType.LONG)
                    {
                        typeSpecifiers.Add(Advance().Value.ToString());
                    }
                }
                else if (currentType == TokenType.FLOAT)
                {
                    if (hasFloat || hasChar || hasShort || hasInt || hasLong || hasDouble || hasVoid)
                        throw Error("类型说明符冲突：float不能与其他基本类型组合");
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasFloat = true;
                    break; // float是完整的类型
                }
                else if (currentType == TokenType.DOUBLE)
                {
                    if (hasDouble || hasChar || hasShort || hasInt || hasFloat || hasVoid)
                        throw Error("类型说明符冲突：double不能与char/short/int/float/void组合");
                    typeSpecifiers.Add(Advance().Value.ToString());
                    hasDouble = true;
                    
                    // 检查是否有long修饰符
                    if (hasLong)
                    {
                        // long double是有效的C99类型
                        typeSpecifiers.Insert(0, "long");
                    }
                    break; // double是完整的类型
                }
                else if (currentType == TokenType.ENUM || currentType == TokenType.STRUCT || currentType == TokenType.UNION)
                {
                    // 枚举、结构体、联合体类型
                    Token  typeToken = Advance();
                    string typeName  = typeToken.Value.ToString();

                    // 如果后面跟着标识符，这个标识符是类型名（如 struct Name）
                    if (Current().Type == TokenType.IDENTIFIER)
                    {
                        typeName += " " + Current().Value.ToString();
                        Advance();
                    }

                    // 包含前置限定符 (const, volatile 等)
                    if (typeSpecifiers.Count > 0)
                        typeName = string.Join(" ", typeSpecifiers) + " " + typeName;

                    return typeName;
                }
                else if (currentType is TokenType.INT8 or TokenType.INT16 or TokenType.INT32 or TokenType.INT64 or
                         TokenType.UINT8 or TokenType.UINT16 or TokenType.UINT32 or TokenType.UINT64 or
                         TokenType.INTPTR_T or TokenType.UINTPTR_T or TokenType.WCHAR_T or TokenType.CHAR32_T or
                         TokenType.SIZE_T or TokenType.SSIZE_T or TokenType.PTRDIFF_T or TokenType.BOOL)
                {
                    // C99 固定宽度整数类型 + _Bool — 仅在尚未收集到其他类型说明符时才作为类型
                    if (typeSpecifiers.Any(t => t != "const" && t != "volatile"))
                        break;
                    typeSpecifiers.Add(Advance().Value.ToString());
                    break;
                }
                else if (currentType == TokenType.IDENTIFIER)
                {
                    // typedef 自定义类型 (如 byte, chtype, size_t)
                    string identName = Current().Value.ToString();
                    if (program.TypeDefs.ContainsKey(identName))
                    {
                        // typedef 类型不是类型说明符组合，直接返回类型名
                        if (typeSpecifiers.Count == 0)
                            return Advance().Value.ToString();
                        // 前面有 const/volatile 等限定符
                        typeSpecifiers.Add(Advance().Value.ToString());
                        break;
                    }
                    // 不是已知 typedef，停止
                    break;
                }
                else
                {
                    // 不是类型说明符，停止解析
                    break;
                }
            }

            // 如果没有收集到任何类型说明符，返回null（可能是自定义类型）
            if (typeSpecifiers.Count == 0)
                return null;

            // 验证类型组合的有效性
            ValidateTypeCombination(hasSigned, hasUnsigned, hasChar, hasShort, hasInt, hasLong, hasFloat, hasDouble, hasVoid);

            // 构建类型字符串
            return string.Join(" ", typeSpecifiers);
        }

        /// <summary>
        /// 验证类型说明符组合的有效性
        /// </summary>
        /// <param name="hasSigned">是否有signed类型</param>
        /// <param name="hasUnsigned">是否有unsigned类型</param>
        /// <param name="hasChar">是否有char类型</param>
        /// <param name="hasShort">是否有short类型</param>
        /// <param name="hasInt">是否有int类型</param>
        /// <param name="hasLong">是否有long类型</param>
        /// <param name="hasFloat">是否有float类型</param>
        /// <param name="hasDouble">是否有double类型</param>
        /// <param name="hasVoid">是否有void类型</param>
        private void ValidateTypeCombination(bool hasSigned, bool hasUnsigned, bool hasChar,  bool hasShort,
                                             bool hasInt,    bool hasLong,     bool hasFloat, bool hasDouble, bool hasVoid)
        {
            // 检查signed/unsigned与类型的兼容性
            if ((hasSigned || hasUnsigned) && (hasFloat || hasDouble || hasVoid))
                throw Error("signed/unsigned不能与float/double/void组合");

            // 检查short/long与类型的兼容性
            if (hasShort && hasLong)
                throw Error("short和long不能同时使用");

            // 检查char的特殊情况：char可以带signed/unsigned，但不能带short/long/int
            if (hasChar && (hasShort || hasInt || hasLong))
                throw Error("char不能与short/int/long组合");

            // 检查float的特殊情况：float不能带long
            if (hasFloat && hasLong)
                throw Error("float不能与long组合");

            // 检查int的默认情况：如果没有指定char/short/long/float/double/void，则默认为int
            if (!hasChar && !hasShort && !hasLong && !hasFloat && !hasDouble && !hasVoid)
            {
                // 只有signed/unsigned，没有具体类型，默认为int
                // 这是有效的：signed, unsigned, signed int, unsigned int
            }
        }

        /// <summary>
        /// 从Token的源代码中提取常量后缀
        /// </summary>
        private string ExtractConstantSuffix(Token token)
        {
            if (string.IsNullOrEmpty(token.SourceLine))
                return "";

            string sourceLine = token.SourceLine;
            int    column     = token.Column - 1; // 转换为0-based索引

            // 检测是否为十六进制数 (0x...)
            bool isHex = (column + 1 < sourceLine.Length && sourceLine[column] == '0' && char.ToLower(sourceLine[column + 1]) == 'x');

            // 找到数字的结束位置（支持整数、小数、科学计数法、十六进制）
            int endPos = column;
            while (endPos < sourceLine.Length && (char.IsDigit(sourceLine[endPos])                                                                             ||
                                                  sourceLine[endPos] == '.'                                                                                    ||
                                                  sourceLine[endPos] == 'e' || sourceLine[endPos] == 'E'                                                        ||
                                                  (endPos > column && (sourceLine[endPos] == '+' || sourceLine[endPos] == '-') && (char.ToUpper(sourceLine[endPos-1]) == 'E')) ||
                                                  (endPos == column + 1 && isHex                && char.ToLower(sourceLine[endPos]) == 'x') ||
                                                  (endPos > column       && isHex               && char.ToLower(sourceLine[endPos]) >= 'a' && char.ToLower(sourceLine[endPos]) <= 'f')))
            {
                endPos++;
            }

            // 提取后缀部分
            string suffix = "";
            while (endPos < sourceLine.Length && char.IsLetter(sourceLine[endPos]))
            {
                suffix += char.ToUpper(sourceLine[endPos]);
                endPos++;
            }

            return suffix;
        }
    }
}  // namespace
